package com.slss.service;
import com.slss.domain.AuditLog; import com.slss.repository.AuditLogRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Propagation; import org.springframework.transaction.annotation.Transactional;
@Service public class AuditService { private final AuditLogRepository repo; public AuditService(AuditLogRepository r){repo=r;} @Transactional public void record(String actor,String action,String targetType,String targetId,String details,String ip,boolean success){save(actor,action,targetType,targetId,details,ip,success);} @Transactional(propagation=Propagation.REQUIRES_NEW) public void recordSecurity(String actor,String action,String targetType,String targetId,String details,String ip,boolean success){save(actor,action,targetType,targetId,details,ip,success);} private void save(String actor,String action,String targetType,String targetId,String details,String ip,boolean success){var log=new AuditLog();log.setActor(actor);log.setAction(action);log.setTargetType(targetType);log.setTargetId(targetId);log.setDetails(details);log.setIpAddress(ip);log.setSuccess(success);repo.save(log);} }
